select id, discount_pct, max(discount_pct) over (partition by channel order by starts_on asc, id asc rows between unbounded preceding and current row) as running_max_discount_pct, min(discount_pct) over (partition by channel order by starts_on asc, id asc rows between unbounded preceding and current row) as running_min_discount_pct, avg(discount_pct) over (partition by channel order by starts_on asc, id asc rows between unbounded preceding and current row) as running_avg_discount_pct from promotions where month(ends_on) in (1, 3, 8)
